                ConversionSentence(14, "Our local football club reached the tournament finals.", "ہمارا مقامی فٹ بال کلب ٹورنامنٹ کے فائنل میں پہنچ گیا۔", "Hamara maqami football club tournament ke final mein pohanch gaya."),
                ConversionSentence(15, "Proper breathing technique prevents workout fatigue.", "سانس لینے کا درست طریقہ ورزش میں جلد تھکنے سے بچاتا ہے۔", "Saans lenay ka durust tareeqa warzish mein jald thaknay se bachata hai."),
                ConversionSentence(16, "I am training hard to run a half marathon next winter.", "میں اگلی سردیوں میں ہاف میراتھن دوڑنے کی سخت تیاری کر رہا ہوں۔", "Mein agli sardiyon mein half marathon dorrnay ki sakht tayari kar raha hoon."),
                ConversionSentence(17, "Badminton is a fantastic sport for agility and endurance.", "بیڈمنٹن چستی اور قوت مدافعت کے لیے ایک زبردست کھیل ہے۔", "Badminton chusti aur quwwat-e-mudafe'at ke liye aik zabardast khel hai."),
                ConversionSentence(18, "Eat protein-rich wholesome food to repair tired muscles.", "تھکے ہوئے پٹھوں کی بحالی کے لیے پروٹین سے بھرپور غذا لیں۔", "Thakay hue patthon ki bahali ke liye protein se bharpoor ghiza lein."),
                ConversionSentence(19, "Warm-up exercises protect your joints from sudden injuries.", "وارم اپ ورزشیں آپ کے جوڑوں کو اچانک چوٹوں سے محفوظ رکھتی ہیں۔", "Warm-up warzishein aap ke jorron ko achanak choton se mahfooz rakhti hain."),
                ConversionSentence(20, "The cricket umpire raised his finger for an LBW decision.", "امپائر نے ایل بی ڈبلیو پر انگلی اٹھا کر آؤٹ قرار دیا۔", "Umpire ne LBW par ungli utha kar out qarar diya."),
                ConversionSentence(21, "Cycling improves cardiovascular health and leg strength.", "سائیکل چلانا دل کی صحت اور ٹانگوں کی طاقت کو بہتر بناتا ہے۔", "Cycle chalana dil ki sehat aur taangon ki taaqat ko behtar banata hai."),
                ConversionSentence(22, "He practices martial arts and holds a black belt in Karate.", "وہ مارشل آرٹس کی مشق کرتا ہے اور کراٹے میں بلیک بیلٹ ہے۔", "Woh martial arts ki mashq karta hai aur karate mein black belt hai."),
                ConversionSentence(23, "Yoga enhances body flexibility, balance, and inner calm.", "یوگا جسم کی لچک، توازن اور اندرونی سکون کو بڑھاتا ہے۔", "Yoga jism ki lachak, tawazun aur androoni sukoon ko barhata hai."),
                ConversionSentence(24, "Always wear supportive athletic running shoes for jogging.", "جاگنگ کے لیے ہمیشہ معیاری اسپورٹس جوتے استعمال کریں۔", "Jogging ke liye hamesha meyaari sports jootay istemal karein."),
                ConversionSentence(25, "The stadium was packed with fifty thousand cheering fans.", "اسٹیڈیم پچاس ہزار پرجوش شائقین سے کھچا کھچ بھرا ہوا تھا۔", "Stadium 50 hazar purjosh shayiqeen se khacha-khach bhara hua tha."),
                ConversionSentence(26, "Discipline in daily training beats raw talent every time.", "روزانہ کی باقاعدہ محنت بغیر محنت کے ہنر کو مات دے دیتی ہے۔", "Rozana ki baqaida mehnat baghair mehnat ke hunar ko maat de deti hai."),
                ConversionSentence(27, "Drink an electrolyte drink on hot summer match days.", "گرمی کے دنوں میں میچ کے دوران نمکیات والا مشروب پئیں۔", "Garmi ke dinon mein match ke dauran namkiyaat wala mashroob piyein."),
                ConversionSentence(28, "Taking rest days is vital for muscle growth and recovery.", "پٹھوں کی مضبوطی اور بحالی کے لیے آرام کے دن ضروری ہیں۔", "Patthon ki mazbooti aur bahali ke liye aaram ke din zaroori hain."),
                ConversionSentence(29, "He bowled a fierce yorker that shattered the stumps.", "اس نے تیز یارکر پھینکی جس نے وکٹیں اکھاڑ دیں۔", "Us ne taiz yorker phainki jis ne wicketein ukhaar dein."),
                ConversionSentence(30, "Fitness is not a temporary trend; it is a lifelong lifestyle.", "فٹنس کوئی عارضی شوق نہیں بلکہ زندگی بھر کا طرزِ حیات ہے۔", "Fitness koi aarzi shauq nahi balkay zindagi bhar ka tarz-e-hayat hai."),
                ConversionSentence(31, "How many pushups and pullups can you do consecutively?", "آپ مسلسل کتنے پش اپس اور پل اپس لگا سکتے ہیں؟", "Aap musalsal kitnay pushups aur pullups laga saktay hain?"),
                ConversionSentence(32, "A thirty-minute brisk walk daily reduces heart risks.", "روزانہ تیس منٹ تیز قدموں کی واک دل کی بیماریوں سے بچاتی ہے۔", "Rozana 30 minute taiz qadmon ki walk dil ki bimariyon se bachati hai."),
                ConversionSentence(33, "Squats build powerful legs and improve core stability.", "اسکواٹس ٹانگوں کو طاقتور اور جسمانی توازن کو بہتر بناتے ہیں۔", "Squats taangon ko taqatwar aur jismani tawazun ko behtar banatay hain."),
                ConversionSentence(34, "Our school cricket team won the inter-city championship cup.", "ہماری اسکول کرکٹ ٹیم نے انٹر سٹی چیمپئن شپ ٹرافی جیت لی۔", "Hamari school cricket team ne inter-city championship trophy jeet li."),
                ConversionSentence(35, "Avoid overtraining to prevent burnout and muscle strains.", "تھکن اور پٹھوں کے کھنچاؤ سے بچنے کے لیے حد سے زیادہ ورزش نہ کریں۔", "Thakan aur patthon ke khinchao se bachnay ke liye hadd se zyada warzish na karein."),
                ConversionSentence(36, "He made a breathtaking catch diving near the boundary line.", "اس نے باؤنڈری لائن کے قریب ہوا میں غوطہ لگا کر شاندار کیچ پکڑا۔", "Us ne boundary line ke qareeb hawa mein ghota laga kar shandar catch pakrra."),
                ConversionSentence(37, "Eat wholesome fruits and almonds before your workout session.", "ورزش شروع کرنے سے پہلے تازہ پھل اور بادام کھائیں۔", "Warzish shuru karne se pehle taaza phal aur badaam khayein."),
                ConversionSentence(38, "Maintain a straight spine when lifting heavy weights.", "وزن اٹھاتے وقت اپنی کمر کو ہمیشہ بالکل سیدھا رکھیں۔", "Wazan uthaatay waqt apni kamar ko hamesha bilkul seedha rakhein."),
                ConversionSentence(39, "The referee blew the whistle to signal the end of the game.", "ریفری نے میچ کے اختتام کی سیٹی بجا دی۔", "Referee ne match ke ikhtitaam ki seeti baja di."),
                ConversionSentence(40, "Sportsmanship teaches us how to win with grace and lose with dignity.", "کھلاڑی کا جذبہ جیت میں عاجزی اور ہار میں وقار سکھاتا ہے۔", "Khilari ka jazba jeet mein aajzi aur haar mein waqaar sikhata hai."),
                ConversionSentence(41, "I love hiking up mountain trails on cool autumn mornings.", "خوشگوار صبح میں پہاڑی راستوں پر چڑھنا میرا پسندیدہ کھیل ہے۔", "Khushgawar subah mein pahari raston par charrhna mera pasandeeda khel hai."),
                ConversionSentence(42, "Staying active keeps your energy levels high all day long.", "متحرک رہنا سارا دن جسم میں چستی اور توانائی برقرار رکھتا ہے۔", "Mutaharrik rehna sara din jism mein chusti aur tawanaai barqarar rakhta hai."),
                ConversionSentence(43, "He won the gold medal in the hundred-meter sprint.", "اس نے سو میٹر کی دوڑ میں گولڈ میڈل جیتا۔", "Us ne 100 meter ki dorr mein gold medal jeeta."),
                ConversionSentence(44, "Team chemistry is essential to win tough tournaments.", "مشکل مقابلے جیتنے کے لیے ٹیم کا باہمی تال میل لازمی ہے۔", "Mushkil muqablay jeetnay ke liye team ka baahmi taal-mail laazmi hai."),
                ConversionSentence(45, "A healthy outside starts from healthy nutrition from the inside.", "خوبصورت اور مضبوط جسم اندرونی اچھی خوراک سے بنتا ہے۔", "Khubsurat aur mazboot jism androoni achi khorak se banta hai."),
                ConversionSentence(46, "Track your physical progress weekly instead of daily.", "روزانہ کے بجائے ہر ہفتے اپنی جسمانی ترقی کا معائنہ کریں۔", "Rozana ke bajaye har haftay apni jismani taraqi ka muaina karein."),
                ConversionSentence(47, "He is a phenomenal captain who leads his team by example.", "وہ ایک زبردست کپتان ہے جو خود مثال بن کر ٹیم کی رہنمائی کرتا ہے۔", "Woh aik zabardast kaptaan hai jo khud misaal ban kar team ki rehnumai karta hai."),
                ConversionSentence(48, "Never underestimate the power of consistent daily effort.", "روزانہ کی مستقل محنت کی طاقت کو کبھی کم مت سمجھیں۔", "Rozana ki mustaqil mehnat ki taaqat ko kabhi kam mat samjhein."),
                ConversionSentence(49, "Physical health and spiritual peace go hand in hand.", "جسمانی صحت اور روحانی سکون ایک دوسرے کے ساتھ جڑے ہیں۔", "Jismani sehat aur roohani sukoon aik doosray ke sath jurray hain."),
                ConversionSentence(50, "Keep training with heart, dedication, and unwavering focus!", "لگن، محنت اور غیر متزلزل توجہ کے ساتھ اپنی مشق جاری رکھیں!", "Lagan, mehnat aur ghair mutazalzil tawajjo ke sath apni mashq jaari rakhein!")
