                ConversionSentence(12, "Iron your dress shirts with steam for a crisp, wrinkle-free look.", "قمیضوں کو شکنوں سے پاک کرنے کے لیے بھاپ والی استری کریں۔", "Qameezon ko shikanon se paak karne ke liye bhaap wali istri karein."),
                ConversionSentence(13, "Wear warm woolen thermal layers to protect against harsh winds.", "سرد ہواؤں سے بچنے کے لیے اندر گرم تھرمل ضرور پہنیں۔", "Sard hawaon se bachnay ke liye andar garam thermal zaroor pehnein."),
                ConversionSentence(14, "Dark navy and charcoal suits are standard for corporate meetings.", "دفتری میٹنگز کے لیے نیوی بلیو اور سرمئی سوٹ معیاری سمجھے جاتے ہیں۔", "Daftari meetings ke liye navy blue aur surmayi suit meyaari samjhay jaatay hain."),
                ConversionSentence(15, "Where can I find premium Boski and Karandi fabric in Lahore?", "لاہور میں بوسکی اور کرنڈی کا بہترین کپڑا کہاں سے ملتا ہے؟", "Lahore mein Boski aur Karandi ka behtareen kapra kahan se milta hai?"),
                ConversionSentence(16, "These hand-embroidered Peshawari chappals are very sturdy.", "یہ ہاتھ سے سلی ہوئی پشاوری چپلیں بہت پائیدار اور خوبصورت ہیں۔", "Yeh haath se sili hui Peshawari chappalein bohat payedaar hain."),
                ConversionSentence(17, "Make sure the collar button is fastened comfortably around neck.", "دیکھیں کہ کالر کا بٹن گلے پر آرام سے بند ہو رہا ہو۔", "Dekhein ke collar ka button galay par aaram se band ho raha ho."),
                ConversionSentence(18, "Neutral shades like beige and olive blend gracefully with anything.", "ہلکے بادامی اور زیتونی رنگ ہر لباس کے ساتھ اچھے لگتے ہیں۔", "Halkay baadami aur zaitooni rang har libaas ke sath achay lagtay hain."),
                ConversionSentence(19, "She designed an exclusive bridal couture collection for fashion week.", "اس نے فیشن ویک کے لیے دلہنوں کے ملبوسات کا نیا مجموعہ تیار کیا۔", "Us ne fashion week ke liye dulhanon ke malboosaat ka naya majmooa tayar kiya."),
                ConversionSentence(20, "Comfort should always be your top priority in daily fashion.", "روزمرہ کے فیشن میں آرام دہ ہونا ہمیشہ اولین ترجیح ہونا چاہیے۔", "Rozmarrah ke fashion mein aaram deh hona hamesha awaleen tarjeeh hona chahiye."),
                ConversionSentence(21, "Can you replace the broken zipper on this winter parka?", "کیا آپ اس ونٹر پارک جیکٹ کا ٹوٹا ہوا زپ تبدیل کر سکتے ہیں؟", "Kya aap is winter parka jacket ka toota hua zip tabdeel kar saktay hain?"),
                ConversionSentence(22, "Khadi fabric has an authentic rustic charm and earthy feel.", "کھدر کے کپڑے میں ایک دیسی اور خالص روایتی کشش ہوتی ہے۔", "Khaddar ke kapray mein aik desi aur khalis riwayati kashish hoti hai."),
                ConversionSentence(23, "A neat leather wristwatch complements any formal attire.", "چمڑے کے پٹے والی صاف ستھری گھڑی ہر سوٹ کے ساتھ خوب جچتی ہے۔", "Chamrray ke pattay wali saaf suthri gharri har suit ke sath khoob jachti hai."),
                ConversionSentence(24, "Wash dark colors separately to avoid accidental color bleeding.", "رنگ اترنے سے بچنے کے لیے گہرے رنگ کے کپڑے الگ دھوئیں۔", "Rang utarnay se bachnay ke liye gehray rang ke kapray alag dhoein."),
                ConversionSentence(25, "Traditional Ajrak shawls represent timeless Sindhi heritage.", "روایتی اجرک کی چادریں سندھ کے لازوال ثقافتی ورثے کی عکاسی کرتی ہیں۔", "Riwayati Ajrak ki chaadrein Sindh ke la-zawal saqafati virsay ki akkasi karti hain."),
                ConversionSentence(26, "This waist belt is made of 100% genuine full-grain leather.", "یہ بیلٹ سو فیصد اصلی اور معیاری چمڑے سے تیار کی گئی ہے۔", "Yeh belt sau feesad asli aur meyaari chamrray se tayar ki gayi hai."),
                ConversionSentence(27, "Polishing your formal shoes daily keeps the leather supple.", "روزانہ جوتوں کو پالش کرنا چمڑے کو نرم اور چمکدار رکھتا ہے۔", "Rozana jooton ko polish karna chamrray ko narm aur chamakdaar rakhta hai."),
                ConversionSentence(28, "He wore a classic black Sherwani for his wedding reception.", "اس نے ولیمے کی تقریب پر کلاسک کالی شیروانی زیب تن کی۔", "Us ne walimay ki taqreeb par classic kaali sherwani zaib-e-tan ki."),
                ConversionSentence(29, "Avoid fast fashion trends; invest in durable timeless pieces.", "عارضی فیشن کے بجائے ہمیشہ پائیدار اور کلاسیک لباس خریدیں۔", "Aarzi fashion ke bajaye hamesha payedaar aur classic libaas khareedein."),
                ConversionSentence(30, "Good posture makes any outfit look tenfold more distinguished.", "سیدھے کھڑے ہونے کا سلیقہ ہر لباس کو دس گنا زیادہ باوقار بناتا ہے۔", "Seedhay kharray honay ka saleeqa har libaas ko das guna zyada ba-waqaar banata hai."),
                ConversionSentence(31, "Can I get this cuff altered to fit my wrist properly?", "کیا یہ کف میری کلائی کے سائز کے مطابق ٹھیک ہو سکتا ہے؟", "Kya yeh cuff meri kalai ke size ke mutabiq theek ho sakta hai?"),
                ConversionSentence(32, "This woolen shawl provides warmth during freezing hill station trips.", "یہ اون کی شال مری اور شمالی علاقوں کی شدید سردی میں حرارت دیتی ہے۔", "Yeh oon ki shawl Murree aur shumali ilaaqon ki shadeed sardi mein hararat deti hai."),
                ConversionSentence(33, "Choose shoes that provide excellent arch support for walking.", "ایسے جوتے منتخب کریں جو چلنے کے دوران پاؤں کو مکمل سہارا دیں۔", "Aisay jootay muntakhib karein jo chalnay ke dauran paon ko sahara dein."),
                ConversionSentence(34, "Subtle perfume applied to pulse points lasts all day long.", "کلائی اور گردن پر ہلکا پرفیوم لگانا سارا دن مہکتا رہتا ہے۔", "Kalai aur gardan par halka perfume lagana sara din mehakta rehta hai."),
                ConversionSentence(35, "The tailors in Anarkali bazaar are renowned for bridal embroidery.", "انارکلی بازار کے درزی دلہن کی کڑھائی کے لیے مشہور ہیں۔", "Anarkali bazaar ke darzi dulhan ki karhai ke liye mashhoor hain."),
                ConversionSentence(36, "A navy blazer paired with khaki trousers is a timeless look.", "نیوی بلیو بلیزر کے ساتھ خاکی پتلون ہمیشہ فیشن میں رہتی ہے۔", "Navy blue blazer ke sath khaki patloon hamesha fashion mein rehti hai."),
                ConversionSentence(37, "Hang your heavy winter coats on sturdy wooden hangers.", "سردیوں کے وزنی کوٹ لکڑی کے مضبوط ہینگرز پر لٹکائیں۔", "Sardiyon ke wazni coat lakri ke mazboot hangers par latkayein."),
                ConversionSentence(38, "The lining inside this suit jacket is made of smooth satin.", "کوٹ کے اندر کا استر نرم اور چمکدار ساٹن سے بنا ہے۔", "Coat ke andar ka astar narm aur chamakdaar satin se bana hai."),
                ConversionSentence(39, "Dress respectfully according to the occasion and venue.", "ہمیشہ تقریب اور جگہ کے احترام کو مدنظر رکھ کر لباس پہنیں۔", "Hamesha taqreeb aur jagah ke ihtiram ko madd-e-nazar rakh kar libaas pehnein."),
                ConversionSentence(40, "A bright smile and kind manners are the finest accessories.", "ایک روشن مسکراہٹ اور اچھا اخلاق ہی انسان کا بہترین زیور ہے۔", "Aik roshan muskurahat aur acha ikhlaaq hi insaan ka behtareen zewar hai."),
                ConversionSentence(41, "Do you sell organic cotton shirts without synthetic polyester?", "کیا آپ کے پاس بغیر پولیسٹر کے خالص سوتی شرٹس ہیں؟", "Kya aap ke paas baghair polyester ke khalis sooti shirts hain?"),
                ConversionSentence(42, "This trench coat protects from heavy wind and rain showers.", "یہ ٹرینچ کوٹ تیز ہوا اور بارش کی پھوار سے مکمل بچاتا ہے۔", "Yeh trench coat taiz hawa aur barish ki phuwaar se mukammal bachata hai."),
                ConversionSentence(43, "Ensure your clothes are thoroughly dried before packing away.", "کپڑوں کو سنبھالنے سے پہلے یقینی بنائیں کہ وہ اچھی طرح خشک ہوں۔", "Kapron ko sambhalnay se pehle yaqeeni banayein ke woh achi tarah khushk hon."),
                ConversionSentence(44, "Traditional Kashmiri embroidery is admired around the globe.", "روایتی کشمیری کڑھائی کو پوری دنیا میں قدر کی نگاہ سے دیکھا جاتا ہے۔", "Riwayati Kashmiri karhai ko poori dunya mein qadr ki nigah se dekha jata hai."),
                ConversionSentence(45, "A clean white crisp dress shirt is a staple in every wardrobe.", "ایک صاف ستھری سفید قمیض ہر الماری کی بنیادی ضرورت ہوتی ہے۔", "Aik saaf suthri safaid qameez har almari ki bunyadi zaroorat hoti hai."),
                ConversionSentence(46, "Dress with modesty, elegance, self-respect, and quiet confidence.", "حیا، وقار، خودداری اور اعتماد کے ساتھ لباس زیب تن کریں۔", "Haya, waqaar, khud-daari aur aitemad ke sath libaas zaib-e-tan karein."),
                ConversionSentence(47, "These breathable socks prevent sweat and foot odor.", "یہ معیاری جرابیں پسینے اور پاؤں کی بو سے محفوظ رکھتی ہیں۔", "Yeh meyaari jurrabein paseenay aur paon ki boo se mahfooz rakhti hain."),
                ConversionSentence(48, "He takes great care of his clothing and personal grooming.", "وہ اپنے لباس اور ذاتی بناؤ سنگھار کا بہت خیال رکھتا ہے۔", "Woh apne libaas aur zaati banav-singhar ka bohat khayal rakhta hai."),
                ConversionSentence(49, "Confidence is what truly elevates any outfit you wear.", "آپ کا اعتماد ہی دراصل ہر لباس کو پرکشش اور باوقار بناتا ہے۔", "Aap ka aitemad hi dar-asal har libaas ko pur-kashish banata hai."),
                ConversionSentence(50, "Wishing you a smart, stylish, and dignified appearance always!", "اللہ تعالیٰ آپ کے انداز کو ہمیشہ شاندار، باوقار اور پرکشش رکھے!", "Allah Ta'ala aap ke andaaz ko hamesha shandar aur ba-waqaar rakhay!")
            )),
            // 28. Home & Housework (50 Sentences)
            ConversionTopic(28, "Home & Housework", "گھر اور گھریلو امور", "home", "Cleaning, household chores, organization, and repairs.", listOf(
                ConversionSentence(1, "Keeping the living room organized brings daily tranquility.", "دیوان خانے کو صاف ستھرا رکھنا روزمرہ کے سکون کا باعث بنتا ہے۔", "Deewan-khanay ko saaf suthra rakhna sukoon ka baais banta hai."),
                ConversionSentence(2, "Could you please sweep and mop the tiled floors today?", "کیا آپ برائے مہربانی آج فرش پر جھاڑو اور پونچھا لگا سکتے ہیں؟", "Kya aap baraye meharbani aaj farsh par jhaaroo aur ponchha laga saktay hain?"),
                ConversionSentence(3, "I need to change the bedsheets and pillow covers this morning.", "مجھے آج صبح بستر کی چادریں اور تکیوں کے غلاف تبدیل کرنے ہیں۔", "Mujhe aaj subah bistar ki chaadrein aur takiyon ke ghilaaf tabdeel karne hain."),
                ConversionSentence(4, "The kitchen sink drain is blocked, we must call a plumber.", "باورچی خانے کا نل بند ہو گیا ہے، پلمبر کو بلانا پڑے گا۔", "Bawarchi-khanay ka nal band ho gaya hai, plumber ko bulana parray ga."),
                ConversionSentence(5, "Please hang the wet laundry outside on the rooftop clothesline.", "براہ کرم گیلے کپڑے چھت پر دھوپ میں تار پر ڈال دیں۔", "Barah-e-karam geelay kapray chhat par dhoop mein taar par daal dein."),
                ConversionSentence(6, "Dusting the bookshelves and window blinds prevents allergies.", "کتابوں اور کھڑکیوں کی مٹی صاف کرنے سے الرجی سے بچاؤ رہتا ہے۔", "Kitabon aur khirkiyon ki mitti saaf karne se allergy se bachao rehta hai."),
                ConversionSentence(7, "We should declutter the attic and donate unused clothes.", "ہمیں اسٹور روم کی فالتو چیزیں اور پرانے کپڑے خیرات کرنے چاہییں۔", "Humein store room ki faaltu cheezon aur kapray khairat karne chahiyein."),
                ConversionSentence(8, "The ceiling fan needs cleaning before the summer season arrives.", "گرمیوں کی آمد سے پہلے چھت کے پنکھوں کی صفائی ضروری ہے۔", "Garmiyon ki aamad se pehle chhat ke pankhon ki safaai zaroori hai."),
                ConversionSentence(9, "Remember to turn off all electrical switches before leaving home.", "گھر سے نکلتے وقت تمام بجلی کے بٹن بند کرنا یاد رکھیں۔", "Ghar se nikaltay waqt bijli ke tamam button band karna yaad rakhein."),
                ConversionSentence(10, "A clean and fragrant home welcomes angelic blessings and peace.", "صاف ستھرا اور خوشبودار گھر برکتوں اور سکون کا گہوارہ ہوتا ہے۔", "Saaf suthra aur khushbodaar ghar barkaton aur sukoon ka gehwara hota hai."),
                ConversionSentence(11, "Where did you place the vacuum cleaner and spare bags?", "آپ نے ویکیوم کلینر اور اس کے فالتو بیگز کہاں رکھے ہیں؟", "Aap ne vacuum cleaner aur us ke faaltu bags kahan rakhay hain?"),
                ConversionSentence(12, "I will vacuum the living room carpets thoroughly this afternoon.", "میں آج دوپہر کو دیوان خانے کے قالینوں کو ویکیوم کروں گا۔", "Mein aaj dopahar ko deewan-khanay ke qaleenon ko vacuum karunga."),
                ConversionSentence(13, "Please wipe down the dining table after finishing lunch.", "دوپہر کے کھانے کے بعد کھانے کی میز کو کپڑے سے صاف کر دیں۔", "Dopahar ke khanay ke baad khanay ki maiz ko saaf kar dein."),
                ConversionSentence(14, "The bathroom mirror has water stains; use glass cleaner.", "باتھ روم کے شیشے پر داغ ہیں، شیشہ صاف کرنے والا اسپرے استعمال کریں۔", "Bathroom ke sheeshay par daagh hain, glass cleaner spray istemal karein."),
                ConversionSentence(15, "We need to replace the burnt-out LED bulb in the hallway.", "راہداری میں فیوز ہوا ایل ای ڈی بلب تبدیل کرنے کی ضرورت ہے۔", "Rahdari mein fuse hua LED bulb tabdeel karne ki zaroorat hai."),
                ConversionSentence(16, "Empty the kitchen waste bin and tie the garbage bag securely.", "باورچی خانے کا کوڑے دان خالی کر کے کچرے کے تھیلے کو گرہ لگائیں۔", "Bawarchi-khanay ka kooradan khaali kar ke thelay ko girah lagayein."),
                ConversionSentence(17, "Keep toxic cleaning chemicals locked away from small children.", "صفائی والے کیمیکلز کو چھوٹے بچوں کی پہنچ سے ہمیشہ دور رکھیں۔", "Safaai walay chemicals ko bachon ki pohanch se hamesha door rakhein."),
                ConversionSentence(18, "The front garden lawn needs mowing and fresh watering.", "سامنے والے لان کی گھاس کاٹنے اور پودوں کو پانی دینے کی ضرورت ہے۔", "Samnay walay lawn ki ghaas kaatnay aur paani denay ki zaroorat hai."),
                ConversionSentence(19, "Please water the potted plants on the balcony every evening.", "شام کے وقت بالکونی کے گملوں کو روزانہ پانی دیں۔", "Shaam ke waqt balcony ke gamlon ko rozana paani dein."),
                ConversionSentence(20, "Organizing your wardrobe by color makes finding clothes effortless.", "الماری میں کپڑوں کو رنگ کے لحاظ سے ترتیب دینا آسان بنا دیتا ہے۔", "Almari mein kapron ko rang ke lehaaz se tarteeb dena aasan banata hai."),
                ConversionSentence(21, "The washing machine finished the spin cycle; hang the clothes.", "واشنگ مشین نے اسپن کا مرحلہ مکمل کر لیا ہے، کپڑے لٹکا دیں۔", "Washing machine ne spin mukammal kar liya hai, kapray latka dein."),
                ConversionSentence(22, "Iron the school uniforms and hang them in the kids' closet.", "اسکول کی وردیوں کو استری کر کے بچوں کی الماری میں لٹکا دیں۔", "School ki wardiyon ko istri kar ke bachon ki almari mein latka dein."),
                ConversionSentence(23, "We should inspect the rooftop for any rainwater leakage signs.", "ہمیں بارش کے پانی کے رساؤ کی جانچ کے لیے چھت چیک کرنی چاہیے۔", "Humein barish ke paani ke rasao ke liye chhat check karni chahiye."),
                ConversionSentence(24, "Fixing minor home repairs early prevents major costly damages.", "گھر کے چھوٹے نقائص جلد ٹھیک کرنا بڑے نقصانات سے بچاتا ہے۔", "Ghar ke chhotay nuqais jald theek karna baray nuqsan se bachata hai."),
                ConversionSentence(25, "Please scrub the kitchen stove burners with soapy water.", "چولہے کے برنرز کو صابن والے گرم پانی سے اچھی طرح رگڑیں۔", "Choolhay ke burners ko saban walay paani se achi tarah ragrein."),
                ConversionSentence(26, "The refrigerator needs defrosting and a thorough wipe down.", "فریج کو ڈی فراسٹ کر کے اندر سے مکمل صاف کرنے کی ضرورت ہے۔", "Fridge ko defrost kar ke andar se mukammal saaf karne ki zaroorat hai."),
                ConversionSentence(27, "Check the pantry for expired spices and canned goods.", "اسٹور میں پرانے مصالحہ جات اور ایکسپائرڈ ڈبوں کی جانچ کریں۔", "Store mein puranay masalajat aur expired dabbon ki jaanch karein."),
                ConversionSentence(28, "Air out the bedrooms by opening windows for fresh air.", "کمروں کی کھڑکیاں کھول کر تازہ ہوا کو اندر آنے دیں۔", "Kamron ki khirkiyan khol kar taaza hawa ko andar aanay dein."),
                ConversionSentence(29, "Use baking soda and vinegar to clear mild sink blockages.", "سنک کی ہلکی بندش دور کرنے کے لیے بیکنگ سوڈا اور سرکہ ڈالیں۔", "Sink ki bandish door karne ke liye baking soda aur sirka daalein."),
                ConversionSentence(30, "A well-kept house brings health, happiness, and peace of mind.", "سلیقے سے سنبھالا ہوا گھر صحت، خوشی اور ذہنی سکون لاتا ہے۔", "Saleeqay se sambhala hua ghar sehat aur zehni sukoon laata hai."),
                ConversionSentence(31, "Can you help me assemble this new wooden shoe rack?", "کیا آپ جوتوں کا یہ نیا لکڑی کا ریک جوڑنے میں میری مدد کریں گے؟", "Kya aap jooton ka yeh naya lakri ka rack jorrnay mein madad karein ge?"),
                ConversionSentence(32, "Tighten the loose screw on the bedroom door handle.", "کمرے کے دروازے کے ہینڈل کا ڈھیلا پیچ کس دیں۔", "Kamray ke darwazay ke handle ka dheela paich kas dein."),
                ConversionSentence(33, "Please organize the shoe cabinet near the front entrance.", "مین گیٹ کے پاس جوتوں کی الماری کو سلیقے سے ترتیب دیں۔", "Main gate ke paas jooton ki almari ko saleeqay se tarteeb dein."),
                ConversionSentence(34, "We should wash the window curtains before the festive Eid holiday.", "عید سے پہلے ہمیں کھڑکیوں کے پردے دھو لینے چاہییں۔", "Eid se pehle humein khirkiyon ke parday dho lenay chahiyein."),
                ConversionSentence(35, "Keep fire safety blankets and first aid boxes easily accessible.", "فرسٹ ایڈ بکس کو ایسی جگہ رکھیں جہاں سے باآسانی مل سکے۔", "First aid box ko aisi jagah rakhein jahan se ba-aasani mil sakay."),
                ConversionSentence(36, "The water motor tank is full; turn off the main pump.", "پانی کی ٹینکی بھر گئی ہے، موٹر کا سوئچ بند کر دیں۔", "Paani ki tanki bhar gayi hai, motor ka switch band kar dein."),
                ConversionSentence(37, "Clean the air filter meshes of the split AC units monthly.", "اسپلٹ اے سی کی جالیاں ہر مہینے صاف کرنا لازمی ہے۔", "Split AC ki jaaliyan har maheenay saaf karna laazmi hai."),
                ConversionSentence(38, "Sweep the front porch driveway to remove fallen autumn leaves.", "خزاں کے گرے ہوئے سوکھے پتے ہٹانے کے لیے صحن میں جھاڑو دیں۔", "Khizan ke giray hue pattay hatanay ke liye sehan mein jhaaroo dein."),
                ConversionSentence(39, "Check the smoke detectors and replace batteries when chirping.", "دھواں جانچنے والے آلات کی بیٹریاں باقاعدگی سے چیک کریں۔", "Dhuwan jaanchne walay aalaat ki batteries check karein."),
                ConversionSentence(40, "Sharing household chores equally creates family harmony.", "گھر کے کام مل بانٹ کر کرنے سے محبت اور یگانگت بڑھتی ہے۔", "Ghar ke kaam mil baant kar karne se mohabbat barhti hai."),
                ConversionSentence(41, "Please fold the clean dry laundry and put it in wardrobes.", "خشک کپڑوں کی تہہ لگا کر انہیں الماریوں میں رکھ دیں۔", "Khushk kapron ki teh laga kar unhein almariyon mein rakh dein."),
                ConversionSentence(42, "Wipe the microwave interior with lemon steam to remove odors.", "مائیکروویو سے بو ختم کرنے کے لیے لیموں کے پانی کی بھاپ دیں۔", "Microwave se boo khatam karne ke liye neembu ke paani ki bhaap dein."),
