                ConversionSentence(5, "Please weigh two kilograms of sweet Sindhri mangoes.", "سندھڑی آم کے دو کلو وزن کر کے تول دیں۔", "Sindhri aam ke do kilo wazan kar ke tol dein."),
                ConversionSentence(6, "Is there a special promotional discount on cooking oil today?", "کیا آج کھانا پکانے کے تیل پر کوئی خصوصی رعایت ہے؟", "Kya aaj cooking oil par koi khusoosi riayat hai?"),
                ConversionSentence(7, "Could you please tell me which aisle has whole spices?", "کیا آپ بتا سکتے ہیں کہ ثابت مصالحہ جات کس قطار میں ہیں؟", "Kya aap bata saktay hain ke saabit masalajat kis qitaar mein hain?"),
                ConversionSentence(8, "Check the production and expiration dates printed on carton.", "ڈبے پر لکھی تیاری اور ایکسپائری کی تاریخیں ضرور چیک کریں۔", "Dabbay par likhi tayari aur expiry ki tareekhein zaroor check karein."),
                ConversionSentence(9, "I will take three liters of full cream pasteurized milk.", "میں تین لیٹر خالص پاسچرائزڈ فل کریم دودھ لوں گا۔", "Mein teen liter khalis pasteurized full cream doodh loonga."),
                ConversionSentence(10, "Always prepare a written shopping checklist before visiting store.", "اسٹور جانے سے پہلے خریداری کی فہرست ہمیشہ پہلے تیار کریں۔", "Store jaanay se pehle khareedari ki fehrist hamesha pehle tayar karein."),
                ConversionSentence(11, "Do you sell organic unprocessed raw blossom honey?", "کیا آپ کے پاس خالص جنگلی پھولوں کا کچا شہد موجود ہے؟", "Kya aap ke paas khalis jungli phoolon ka kacha shehad hai?"),
                ConversionSentence(12, "Where are the hygiene items, dishwashing soap, and detergents?", "صابن، سرف اور برتن دھونے کا سامان کس قطار میں ہے؟", "Saban, surf aur bartan dhonay ka saman kis qitaar mein hai?"),
                ConversionSentence(13, "Are these imported breakfast cereals sugar-free and gluten-free?", "کیا یہ امپورٹڈ سیریل چینی اور گلوٹین سے پاک ہیں؟", "Kya yeh imported cereals cheeni aur gluten se paak hain?"),
                ConversionSentence(14, "Please give me half a kilogram of fresh minced beef.", "براہ کرم مجھے آدھا کلو تازہ گائے کا قیمہ بنا کر دیں۔", "Barah-e-karam mujhe aadha kilo taaza gaye ka qeema bana kar dein."),
                ConversionSentence(15, "Can you slice this whole block of cheddar cheese thinly?", "کیا آپ چیز کے اس ٹکڑے کے باریک سلائس کاٹ سکتے ہیں؟", "Kya aap cheese ke is tukray ke bareek slice kaat saktay hain?"),
                ConversionSentence(16, "Where can I find biodegradable, eco-friendly shopping bags?", "ماحول دوست کاغذی تھیلے کہاں سے مل سکتے ہیں؟", "Mahool dost kaghazi thelay kahan se mil saktay hain?"),
                ConversionSentence(17, "This shopping trolley has a jammed wheel; let me swap it.", "اس شاپنگ ٹرالی کا پہیہ پھنس رہا ہے، میں دوسری لے لیتا ہوں۔", "Is shopping trolley ka pahiya phans raha hai, mein doosri le leta hoon."),
                ConversionSentence(18, "Do you have pure olive oil suitable for deep salad dressing?", "کیا سلاد پر ڈالنے کے لیے ایکسٹرا ورجن زیتون کا تیل ہے؟", "Kya salad par daalnay ke liye extra virgin zaitoon ka tail hai?"),
                ConversionSentence(19, "The produce in this section is sourced directly from local farms.", "اس سیکشن کی تمام سبزیاں مقامی فارموں سے تازہ منگوائی گئی ہیں۔", "Is section ki sabziyan maqami farmon se taaza mangwayi gayi hain."),
                ConversionSentence(20, "Is there any express cash counter for five items or fewer?", "کیا پانچ یا اس سے کم اشیاء کے لیے الگ ایکسپریس کاؤنٹر ہے؟", "Kya 5 ya us se kam ashya ke liye alag express counter hai?"),
                ConversionSentence(21, "Please put the fragile glass bottles in a separate carrier bag.", "شیشے کی نازک بوتلیں الگ تھیلے میں ڈال کر دیں۔", "Sheeshay ki naazuk botalain alag thelay mein daal kar dein."),
                ConversionSentence(22, "Do you accept digital wallet payments via smartphone apps?", "کیا آپ موبائل ایپس اور ڈیجیٹل والٹ سے ادائیگی لیتے ہیں؟", "Kya aap mobile apps aur digital wallet se payment letay hain?"),
                ConversionSentence(23, "The cash register gave me an itemized printed receipt.", "کیش کاؤنٹر نے مجھے تمام اشیاء کی تفصیل والی رسید دی۔", "Cash counter ne mujhe tamam ashya ki tafseel wali raseed di."),
                ConversionSentence(24, "Keep your receipt in case you need to return any sealed items.", "اگر کوئی چیز تبدیل کروانی ہو تو رسید سنبھال کر رکھیں۔", "Agar koi cheez tabdeel karwani ho to raseed sambhal kar rakhein."),
                ConversionSentence(25, "Where is the bakery counter for freshly baked bread and buns?", "تازہ بیکری کی ڈبل روٹی اور بنز کا کاؤنٹر کس طرف ہے؟", "Taaza bakery ki double roti aur buns ka counter kis taraf hai?"),
                ConversionSentence(26, "These fresh strawberries and apples smell wonderfully sweet.", "یہ تازہ اسٹرابری اور سیب بہت خوشبودار اور میٹھے ہیں۔", "Yeh taaza strawberry aur saib bohat meethay hain."),
                ConversionSentence(27, "Do you sell green tea leaves and herbal chamomile tea?", "کیا آپ کے پاس کھلی سبز چائے کی پتی اور قہوہ موجود ہے؟", "Kya aap ke paas sabz chaye ki patti aur qahwa hai?"),
                ConversionSentence(28, "Buying seasonal vegetables saves money and guarantees top nutrition.", "موسمی سبزیاں خریدنا سستا بھی ہوتا ہے اور غذائیت سے بھرپور بھی۔", "Mausami sabziyan khareedna sasta bhi hota hai aur sehat-bakhsh bhi."),
                ConversionSentence(29, "Check the seal on the cooking oil bottle before placing in cart.", "تیل کی بوتل ٹرالی میں رکھنے سے پہلے اس کی مہر ضرور دیکھ لیں۔", "Tail ki botal trolley mein rakhnay se pehle seal zaroor dekh lein."),
                ConversionSentence(30, "Plan your weekly meals to minimize household food wastage.", "کھانے کا ضیاع روکنے کے لیے پورے ہفتے کے کھانوں کی منصوبہ بندی کریں۔", "Khanay ka ziyaa roknay ke liye haftay ke khanon ka plan banayein."),
                ConversionSentence(31, "Where can I find frozen seafood, fish fillets, and prawns?", "فروزن مچھلی اور جھینگے کس فریزر میں رکھے ہیں؟", "Frozen machhli aur jheengay kis freezer mein rakhay hain?"),
                ConversionSentence(32, "This store offers a five percent loyalty reward to members.", "یہ اسٹور کارڈ ممبرز کو پانچ فیصد کی خصوصی رعایت دیتا ہے۔", "Yeh store card members ko 5 feesad ki riayat deta hai."),
                ConversionSentence(33, "Please bring me a head of fresh broccoli and a bunch of spinach.", "ایک تازہ بند گوبھی یا بروکولی اور پالک کی گٹھی لا دیں۔", "Aik taaza band gobhi ya broccoli aur palak ki gutthi laa dein."),
                ConversionSentence(34, "Are these canned kidney beans already boiled and salted?", "کیا کین میں بند لوبیا پہلے سے ابلا ہوا ہے؟", "Kya can mein band lobia pehle se ubla hua hai?"),
                ConversionSentence(35, "Rinse canned beans under tap water before adding to salads.", "سلاد میں شامل کرنے سے پہلے ڈبے والے دانوں کو پانی سے دھو لیں۔", "Salad mein daalnay se pehle dabbi walay danon ko dho lein."),
                ConversionSentence(36, "Do you have crushed whole oats for healthy breakfast porridge?", "کیا ناشتے کے لیے بغیر چینی والا دلیہ (اوٹس) موجود ہے؟", "Kya nashtay ke liye baghair cheeni wala daliya (oats) hai?"),
                ConversionSentence(37, "Where can I find pure almond milk and soya bean milk?", "بادام کا دودھ اور سویا ملک کہاں رکھا ہوا ہے؟", "Badaam ka doodh aur soya milk kahan rakha hua hai?"),
                ConversionSentence(38, "Please ensure the egg carton has no cracked or damaged eggs.", "دیکھ لیں کہ انڈوں کے ڈبے میں کوئی انڈا ٹوٹا ہوا نہ ہو۔", "Dekh lein ke andon ke dabbay mein koi anda toota hua na ho."),
                ConversionSentence(39, "We should buy pantry staples in bulk to take advantage of sales.", "بچت کے لیے دالیں اور آٹا سیل کے دوران اکٹھا خریدنا چاہیے۔", "Bachat ke liye daalein aur aata sale ke dauran ikattha khareedna chahiye."),
                ConversionSentence(40, "The store staff was courteous and assisted in finding items.", "اسٹور کا عملہ بہت شائستہ تھا اور چیزیں تلاش کرنے میں مدد کی۔", "Store ka amla bohat shaista tha aur cheezon mein madad ki."),
                ConversionSentence(41, "Can you help me reach that cereal box on the top shelf?", "کیا اوپر والے خانے سے وہ سیریل کا ڈبہ اتارنے میں مدد کریں گے؟", "Kya ooper walay khanay se woh serial ka dabba utaarein ge?"),
                ConversionSentence(42, "Place the heavy melon and oil cans at the bottom of the cart.", "بھاری خربوزہ اور تیل کے کین ٹرالی کے نچلے حصے میں رکھیں۔", "Bhaari kharbooza aur tail ke can trolley ke neechay rakhein."),
                ConversionSentence(43, "This supermarket provides covered parking with easy ramp access.", "اس سپر مارکیٹ میں گاڑیوں کی محفوظ اور کشادہ پارکنگ ہے۔", "Is supermarket mein gaariyon ki mahfooz parking hai."),
                ConversionSentence(44, "Remember to bring your reusable canvas tote bags from home.", "گھر سے کپڑے کے بنے شاپنگ بیگز ساتھ لانا مت بھولیں۔", "Ghar se kapray ke banay shopping bags sath lana mat bhoolin."),
                ConversionSentence(45, "Freshly ground black peppercorns have an intoxicating aroma.", "تازہ پسی کالی مرچ کی خوشبو انتہائی شاندار ہوتی ہے۔", "Taaza pisi kaali mirch ki khushboo shandar hoti hai."),
                ConversionSentence(46, "Do you stock raw cashews, walnuts, and dried Turkish figs?", "کیا آپ کے پاس کاجو، اخروٹ اور خشک انجیر موجود ہیں؟", "Kya aap ke paas kaju, akhrot aur khushk injeer hain?"),
                ConversionSentence(47, "The checkout queue is moving swiftly thanks to extra counters.", "اضافی کاؤنٹرز کی وجہ سے کیش کی لائن بہت تیزی سے چل رہی ہے۔", "Izafi counters ki wajah se cash ki line taizi se chal rahi hai."),
                ConversionSentence(48, "Check the total bill amount and discount applied on checkout.", "کاؤنٹر پر بل کی کل رقم اور رعایت ضرور چیک کر لیں۔", "Counter par bill ki kul raqam aur riayat zaroor check kar lein."),
                ConversionSentence(49, "Thank you for shopping at our supermarket; see you again!", "ہمارے سپر اسٹور سے خریداری کا شکریہ، دوبارہ تشریف لائیں!", "Hamare super store se khareedari ka shukriya, dobara aayiye ga!"),
                ConversionSentence(50, "May your pantry always be stocked with wholesome sustenance!", "اللہ تعالیٰ آپ کے گھر کو ہمیشہ پاکیزہ رزق اور فراوانی عطا کرے!", "Allah Ta'ala aap ke ghar ko hamesha pakeeza rizq ata karay!")
            ))
        )
    }
}
